def trans_deps(s, t):
    """All tasks t transitively depends on (following dependency edges)."""
    seen = set()
    stack = list(s.dependencies(t))
    while stack:
        d = stack.pop()
        if d in seen:
            continue
        seen.add(d)
        stack.extend(s.dependencies(d))
    return seen

